INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('komplekt-taper-80-noero', 'en', 'Dining Set: Taper 80×80 Table + 4 Noero Chairs (Cappuccino)', 'Furniture sets', 'Refined dining set featuring signature 82 cm slatted Noero chairs in cappuccino tone and a square Taper 80×80 cm table in white marble finish. 130,000 UZS package discount.', '["Стол 80 × 80 × 75 см, 4 стула 82 × 48 × 49 см"]', '{"mat":"металл, литой полипропилен, ЛДСП мрамор","dim":"Стол 80 × 80 × 75 см, 4 стула 82 × 48 × 49 см","maxLoad":"120 кг (на стул)","colors":"White marble / Cappuccino"}', 'Taper 80x80 Table + 4 Noero Chairs Set - BTT Tashkent', 'Buy dining set: square table Taper 80x80 + 4 Noero cappuccino chairs for 1,501,000 UZS by BTT.');
